#include "gtest/gtest.h"

template <typename T> class TT : public ::testing::Test {};
struct Names {
  template <typename T> static std::string GetName(int) {
    return std::is_same<T, std::string>::value ? "std::string" : "int";
  }
};
using Types = ::testing::Types<int, std::string>;
TYPED_TEST_SUITE(TT, Types, Names);

TYPED_TEST(TT, DoesNotExit) {
  // Does not exit, so this should fail with "failed to die".
  EXPECT_EXIT({ fprintf(stderr, "child ran statement\n"); },
              ::testing::ExitedWithCode(0), "");
}
TYPED_TEST(TT, Exits1) {
  EXPECT_EXIT(_exit(1), ::testing::ExitedWithCode(1), "");
}

int main(int argc, char** argv) {
  ::testing::InitGoogleTest(&argc, argv);
  GTEST_FLAG_SET(death_test_style, "threadsafe");
  return RUN_ALL_TESTS();
}
